class Solution {
public:
    int numOfWays(int n) {
        const long long MOD = 1000000007LL;
        // State vector v = [count_ABA, count_ABC], initial row: [6, 6].
        // Transition matrix M = [[3,2],[2,2]].
        // Answer = sum of entries of M^(n-1) * [6, 6], mod 1e9+7.
        long long m00 = 3, m01 = 2, m10 = 2, m11 = 2;
        long long r00 = 1, r01 = 0, r10 = 0, r11 = 1;
        long long e = (long long)(n - 1);
        while (e > 0) {
            if (e & 1LL) {
                long long nr00 = (r00 * m00 + r01 * m10) % MOD;
                long long nr01 = (r00 * m01 + r01 * m11) % MOD;
                long long nr10 = (r10 * m00 + r11 * m10) % MOD;
                long long nr11 = (r10 * m01 + r11 * m11) % MOD;
                r00 = nr00; r01 = nr01; r10 = nr10; r11 = nr11;
            }
            long long nm00 = (m00 * m00 + m01 * m10) % MOD;
            long long nm01 = (m00 * m01 + m01 * m11) % MOD;
            long long nm10 = (m10 * m00 + m11 * m10) % MOD;
            long long nm11 = (m10 * m01 + m11 * m11) % MOD;
            m00 = nm00; m01 = nm01; m10 = nm10; m11 = nm11;
            e >>= 1;
        }
        long long an = (r00 * 6 + r01 * 6) % MOD;
        long long bn = (r10 * 6 + r11 * 6) % MOD;
        return (int)((an + bn) % MOD);
    }
};
